func layerProjectClassPageListItem(profile LayerProfile, value tg.PageListItemClass) (tg.PageListItemClass, bool, error) {
	if value == nil {
		return nil, false, &LayerCodecError{Operation: "project", Profile: profile, Reason: "nil class value"}
	}
	switch value := value.(type) {
	case *tg.PageListItemBlocks:
		projected, keep, err := layerProjectFamilyPageListItemBlocks(profile, value)
		if err != nil || !keep {
			return nil, keep, err
		}
		result, ok := projected.(tg.PageListItemClass)
		if !ok {
			return nil, false, &LayerCodecError{Operation: "project", Profile: profile, Semantic: LayerSemanticTypePageListItemBlocks, Reason: "project hook returned a constructor outside class PageListItem"}
		}
		return result, true, nil
	case *tg.PageListItemText:
		projected, keep, err := layerProjectFamilyPageListItemText(profile, value)
		if err != nil || !keep {
			return nil, keep, err
		}
		result, ok := projected.(tg.PageListItemClass)
		if !ok {
			return nil, false, &LayerCodecError{Operation: "project", Profile: profile, Semantic: LayerSemanticTypePageListItemText, Reason: "project hook returned a constructor outside class PageListItem"}
		}
		return result, true, nil
	default:
		return nil, false, &LayerCodecError{Operation: "project", Profile: profile, Reason: "unknown canonical class constructor"}
	}
}

